import { AnimatePresence, PanInfo, motion } from "framer-motion";
import { PropsWithChildren, useEffect, useMemo, useRef, useState } from "react";
import styles from "./full-page-overlay.module.less";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { Modal } from "@/core/components/primitives/modal/modal";
import { useWindowWidthBreakpoints } from "@/core/hooks/use-window-width-breakpoints";
import EventAggregator, { EVENT_ON_MODAL_CLOSE } from "@/core/helpers/event-aggregator";
import { useContentContainerRef } from "@/core/components/primitives/content-container/content-container";
import { useTranslation } from "react-i18next";

type FullPageOverlayProps = {
  /** Controlled open state. Flip this from `onClose` */
  open: boolean;
  /** Called when the exit animation has finished (close button, swipe or backdrop) */
  onClose: () => void;
  /** Full width on desktop too, instead of the default 35vw panel */
  fullyOpenOnDesktop?: boolean;
  /** Identifies the overlay in the modal-close event. Random when omitted */
  id?: string | number;
  /** Needed for clearer accessibility labeling */
  pageName?: string;
  /** Moves focus to the close button when the overlay opens */
  focusOnCloseButton?: boolean;
};

/**This is the amount of pixels the user needs to swipe from the right to close the overlay. No science behind this number. 300 just "feels good"*/
const X_SWIPE_OFFSET = 300;

/**This is the velocity the user needs to swipe to close the overlay. No science behind this number. 500 just "feels good"*/
const VELOCITY_SWIPE_THRESHOLD = 500;

const LARGE_BREAK_POINT = 1024;

export const FullPageOverlay = ({
  open,
  onClose,
  fullyOpenOnDesktop = false,
  id: inputId,
  pageName,
  focusOnCloseButton,
  children,
}: PropsWithChildren<FullPageOverlayProps>) => {
  const { t } = useTranslation();

  const [isExiting, setIsExiting] = useState(false);
  const wrapperElement = useContentContainerRef();
  const closeButtonRef = useRef<HTMLButtonElement>(null);

  /** find width of the screen to determine animation width and prevent to hasty closing of the overlay */
  const screenWidth = useWindowWidthBreakpoints({
    SMALL: 0,
    LARGE: LARGE_BREAK_POINT,
  });

  const animationWidth = screenWidth === "LARGE" && !fullyOpenOnDesktop ? "35vw" : "100vw";

  const id = useMemo(() => inputId || Math.floor(Math.random() * 1000000 + 1), [inputId]);

  const triggerExitAnimation = () => setIsExiting(true);

  const handleAnimationComplete = () => {
    if (isExiting) {
      EventAggregator.publish(EVENT_ON_MODAL_CLOSE, id); // Trigger the modal's internal logic via the event aggregator
      onClose(); // Call onClose after the animation completes
      setIsExiting(false); // Reset the exit state
    }
  };

  const handleDragEnd = (_e: unknown, { offset, velocity }: PanInfo) => {
    const swipe = offset.x > X_SWIPE_OFFSET || velocity.x > VELOCITY_SWIPE_THRESHOLD;
    if (swipe) triggerExitAnimation();
  };

  useEffect(() => {
    if (open && focusOnCloseButton && closeButtonRef.current) {
      closeButtonRef.current.focus();
    }
  }, [open]);

  return (
    <AnimatePresence>
      <Modal isOpen={open} onClose={triggerExitAnimation} id={id} refWrapperElement={wrapperElement ?? undefined}>
        <motion.div
          initial={{ right: `-${animationWidth}` }}
          animate={{ right: isExiting ? `-${animationWidth}` : 0 }}
          exit={{ right: `-${animationWidth}` }}
          transition={{ duration: 0.4, ease: "easeOut" }}
          drag="x"
          dragConstraints={{ left: 0, right: 3000 }} //Create a high force to prevent the user from dragging the overlay to the right
          dragSnapToOrigin // Snap back to the origin when the user releases the drag
          dragElastic={0}
          dragTransition={{ bounceStiffness: 250, bounceDamping: 30 }}
          onDragEnd={handleDragEnd}
          onAnimationComplete={handleAnimationComplete}
          className={styles.overlay}
          style={{ width: animationWidth }}
          data-is-open={open}
        >
          <PrimaryButton
            ref={closeButtonRef}
            iconCenterNew="close"
            iconSize="xxl"
            onClick={triggerExitAnimation}
            className={styles.closeButton}
            ariaLabel={t("closeFullPageOverlay", [pageName])}
            testId="fullPageOverlayCloseButton"
          />
          {children}
        </motion.div>
      </Modal>
    </AnimatePresence>
  );
};
