import { useState } from "react";
import { Meta, StoryObj } from "@storybook/react";
import { FullPageOverlay } from "./full-page-overlay";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { expect, fn, userEvent, waitFor, within } from "storybook/test";
import { desktopOnlyMode } from "@/storybook/preview";
import { ContentContainer } from "@/core/components/primitives/content-container/content-container";

const BUTTON_TEXT = "Show";
const HEADLINE = "Some nice content";

const meta = {
  title: "Primitives/Full Page Overlay",
  component: FullPageOverlay,
  parameters: {
    layout: "fullscreen",
    docs: {
      // The overlay renders through Modal, which portals it out of the story and positions it fixed
      // over the viewport, so an inline docs preview lets it cover the docs page. Render the preview
      // in an iframe tall enough to show the open panel instead.
      story: { inline: false, height: "35rem" },
      description: {
        component:
          "Overlay panel that slides in from the right and covers the page - full width on mobile, a " +
          "35vw panel on desktop unless `fullyOpenOnDesktop` is set. Closes via the close button, a " +
          "right-swipe or the backdrop, and reports the close via `onClose` once the exit animation " +
          "has finished. The open state is fully controlled.",
      },
    },
  },
  argTypes: {
    id: { table: { disable: true } },
    // The story render owns the open state via its trigger button.
    open: { table: { disable: true } },
    onClose: { table: { disable: true } },
  },
  args: {
    // open/onClose are owned by the story render's trigger button - these values are unused.
    open: false,
    onClose: fn(),
    fullyOpenOnDesktop: false,
    pageName: "Example page",
    focusOnCloseButton: false,
  },
  // The overlay is controlled and starts closed, so every story opens it via a trigger
  // button - the play function clicks it so snapshots capture the open overlay.
  render: function StoryComponent(args) {
    const [isOpen, setIsOpen] = useState(false);
    return (
      <ContentContainer>
        <div>
          <PrimaryButton label={BUTTON_TEXT} onClick={() => setIsOpen(true)} />
          <FullPageOverlay {...args} open={isOpen} onClose={() => setIsOpen(false)}>
            <div style={{ margin: "2rem" }}>
              <h1>{HEADLINE}</h1>
              <p>Very nice content</p>
            </div>
          </FullPageOverlay>
        </div>
      </ContentContainer>
    );
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await userEvent.click(canvas.getByText(BUTTON_TEXT));
    await waitFor(async () => {
      await expect(canvas.getByText(HEADLINE)).toBeVisible();
      await expect(canvas.getByTestId("fullPageOverlayCloseButton")).toBeVisible();
    });
  },
} satisfies Meta<typeof FullPageOverlay>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {};

export const FullyOpenOnDesktop: Story = {
  parameters: {
    chromatic: desktopOnlyMode,
  },
  args: {
    fullyOpenOnDesktop: true,
  },
};

export const VerticalScroll: Story = {
  parameters: {
    chromatic: desktopOnlyMode,
  },
  render: function StoryComponent(args) {
    const [isOpen, setIsOpen] = useState(false);
    return (
      <ContentContainer>
        <div>
          <PrimaryButton label={BUTTON_TEXT} onClick={() => setIsOpen(true)} />
          <FullPageOverlay {...args} open={isOpen} onClose={() => setIsOpen(false)}>
            <div style={{ margin: "2rem" }}>
              <h1>{HEADLINE}</h1>
              {/* Repeat content 50 times to force vertical scroll */}
              {[...Array(50)].map((_, i) => (
                <div key={i}>
                  <p>Very nice content</p>
                </div>
              ))}
            </div>
          </FullPageOverlay>
        </div>
      </ContentContainer>
    );
  },
};

export const TestClose: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await userEvent.click(canvas.getByText(BUTTON_TEXT));
    await waitFor(() => expect(canvas.getByText(HEADLINE)).toBeVisible());
    await userEvent.click(canvas.getByTestId("fullPageOverlayCloseButton"));
    // onClose fires once the exit animation has finished, which unmounts the modal content.
    await waitFor(() => expect(canvas.queryByText(HEADLINE)).not.toBeInTheDocument());
  },
};
